'use client';
import { useState } from 'react';
import { useUser, useFirestore, useDoc, useMemoFirebase } from '@/firebase';
import { addDocumentNonBlocking } from '@/firebase/non-blocking-updates';
import { collection, doc } from 'firebase/firestore';
import { useToast } from '@/hooks/use-toast';
import { createVirtualAccount } from '@/ai/flows/create-virtual-account';

import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Loader2 } from 'lucide-react';
import type { User } from '@/lib/data';

export default function CreateAccountCard() {
  const { user } = useUser();
  const firestore = useFirestore();
  const { toast } = useToast();
  const [isCreating, setIsCreating] = useState(false);

  const userDocRef = useMemoFirebase(
    () => (firestore && user ? doc(firestore, 'users', user.uid) : null),
    [firestore, user]
  );
  const { data: userProfile } = useDoc<User>(userDocRef);

  const handleCreateAccount = async () => {
    if (!user || !userProfile) {
      toast({
        variant: 'destructive',
        title: 'Error',
        description: 'You must be logged in to create an account.',
      });
      return;
    }

    setIsCreating(true);

    try {
      // 1. Call the Genkit flow to get the new account details
      const accountDetails = await createVirtualAccount({
        userId: user.uid,
        firstName: userProfile.firstName,
        lastName: userProfile.lastName,
      });

      // 2. Save the new account to Firestore
      const virtualAccountsCol = collection(firestore, 'virtual_accounts');
      const newAccountRef = doc(virtualAccountsCol);

      await addDocumentNonBlocking(virtualAccountsCol, {
        id: newAccountRef.id,
        userId: user.uid,
        ...accountDetails,
        balance: 0,
        createdAt: new Date().toISOString(),
      });

      toast({
        title: 'Account Created!',
        description: `Your new account ${accountDetails.accountNumber} is ready.`,
      });
    } catch (error) {
      console.error('Error creating virtual account:', error);
      toast({
        variant: 'destructive',
        title: 'Creation Failed',
        description:
          'There was an error creating your virtual account. Please try again.',
      });
    } finally {
      setIsCreating(false);
    }
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>Create a New Account</CardTitle>
        <CardDescription>
          Generate a unique virtual bank account to start receiving funds.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Button
          onClick={handleCreateAccount}
          disabled={isCreating}
          className="w-full"
        >
          {isCreating ? (
            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
          ) : null}
          {isCreating ? 'Generating Account...' : 'Create New Virtual Account'}
        </Button>
      </CardContent>
    </Card>
  );
}
